<script setup>
import {computed} from 'vue';
import {fdate,num} from '../../lib/client-info';
import {loadClientStock} from '../../lib/client-profile-sections';
import {useClientSectionData} from '../../composables/useClientSectionData';
const props=defineProps({bundle:Object});const {data,loading,error,load}=useClientSectionData(()=>props.bundle,'stock',loadClientStock);
const stats=computed(()=>data.value?[['📋','Material requests',data.value.mr.length],['🧴','Requested qty',data.value.mr.reduce((s,d)=>s+(d.items||[]).reduce((n,i)=>n+num(i.qty),0),0)],['📦','Stock entries',data.value.se.length],['📊','Issued qty',data.value.se.reduce((s,e)=>s+e.items.reduce((n,i)=>n+num(i.qty),0),0)]]:[]);
const state=d=>d.workflow_state||d.custom_stock_request_status||(Number(d.docstatus)===1?'Submitted':Number(d.docstatus)===2?'Cancelled':'Draft');
const tone=st=>/cancel|reject/i.test(st)?'neg':/release|approve|submit|issued/i.test(st)?'ok':'warn';
</script>
<template><div class="c3-tab-body"><p v-if="loading" role="status">Loading client stock…</p><p v-if="error" role="alert">{{error}} <button type="button" class="c3-btn" @click="load(true)">Retry</button></p><template v-if="data"><div class="c3-kpis"><div v-for="[icon,label,value] in stats" :key="label" class="c3-kpi"><span class="c3-kpi-ic">{{icon}}</span><div><small>{{label}}</small><b>{{value}}</b></div></div></div><div class="c3-split"><section><h4 class="c3-h4">📋 Material requests</h4><article v-for="d in data.mr" :key="d.name" class="c3-card c3-accent" :class="'tone-'+tone(state(d))"><header class="c3-card-h"><div><b>📋 {{d.name}}</b><small>{{fdate(d.transaction_date||d.creation)}}, {{d.set_warehouse||'—'}}</small></div><span class="c3-pill" :class="'tone-'+tone(state(d))">{{state(d)}}</span></header><div class="c3-mini">{{d.custom_stock_request_type==='Special Material Request'?'Consumable Request':d.custom_stock_request_type||d.material_request_type||'Material Request'}}</div><div class="c3-chips"><span v-for="(i,index) in d.items||[]" :key="i.name||index" class="c3-chip">{{i.item_name||i.item_code}} <b>{{num(i.qty)}} {{i.uom}}</b></span><span v-if="!d.items?.length" class="c3-chip">No items</span></div></article><div v-if="!data.mr.length" class="c3-empty-sm">No material requests for this client.</div></section><section><h4 class="c3-h4">📦 Stock entries</h4><article v-for="e in data.se" :key="e.h.stock_entry" class="c3-card c3-accent" :class="'tone-'+tone(state(e.h))"><header class="c3-card-h"><div><b>📦 {{e.h.stock_entry}}</b><small>{{fdate(e.h.posting_date)}}, {{e.h.purpose||e.h.stock_entry_type||'Stock entry'}}</small></div><span class="c3-pill" :class="'tone-'+tone(state(e.h))">{{state(e.h)}}</span></header><div v-for="(i,index) in e.items" :key="i.name||index" class="c3-stock-item"><b>{{i.item_name||i.item_code}}</b><span>Qty <b>{{num(i.qty)}}</b> {{i.uom}}</span><small>🏬 {{i.s_warehouse||'—'}} → 🏥 {{i.t_warehouse||'Issued'}}</small><small v-if="num(i.custom_released_qty)||num(i.custom_received_qty)">🚚 Released {{num(i.custom_released_qty)}}, ✅ received {{num(i.custom_received_qty)}}<span v-if="num(i.custom_missing_qty)" class="tone-neg">, missing {{num(i.custom_missing_qty)}}</span></small></div></article><div v-if="!data.se.length" class="c3-empty-sm">No stock issued for this client.</div></section></div></template></div></template>
